const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry Definition - Cambodia
  const cambodia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Cambodia'))
    .geometry();

  // 2. Data Acquisition - Hansen Global Forest Change
  const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // Get the loss year band (1-23 represents years 2001-2023)
  const lossYear = hansen.select('lossyear');

  // 3. Filter for forest loss between 2001 and 2014 (years 1-14)
  const loss2001_2014 = lossYear.gte(1).and(lossYear.lte(14));

  // 4. Calculate total forest loss pixels
  const lossStats = loss2001_2014.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: cambodia,
    scale: 3000,
    maxPixels: 1e9
  });

  const totalLossPixels = lossStats.get('lossyear').getInfo();

  // Also get count of valid pixels to check for C2
  const pixelCount = loss2001_2014.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: cambodia,
    scale: 3000,
    maxPixels: 1e9
  });

  const validPixels = pixelCount.get('lossyear').getInfo();

  // 5. Validation & Output
  console.log(`Valid pixels analyzed: ${validPixels}`);
  console.log(`Forest loss pixels (2001-2014): ${totalLossPixels}`);

  if (totalLossPixels === null || totalLossPixels === undefined || isNaN(totalLossPixels)) {
    console.log("<answer>C3</answer>");
  } else if (validPixels === 0) {
    console.log("<answer>C2</answer>");
  } else if (totalLossPixels > 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
